import React, { useState } from 'react';
import { Users, DoorOpen, ChevronDown, ChevronUp, Search, Calendar, Clock, BookOpen } from 'lucide-react';

const GlobalResourceMonitor = ({ allDepartments, globalSchedule }) => {
  const [searchTerm, setSearchTerm] = useState("");
  const [expandedId, setExpandedId] = useState(null);

  // 1. Aggregate all unique Proctors and Rooms across the whole system
  const allProctors = allDepartments.flatMap(d => d.proctors.map(p => ({ ...p, deptCode: d.code })));
  const allRooms = allDepartments.flatMap(d => d.rooms.map(r => ({ ...r, deptCode: d.code })));

  const toggleExpand = (id) => setExpandedId(expandedId === id ? null : id);

  // Helper to find assignments in the global schedule
  const getAssignments = (nameOrNumber, type) => {
    return globalSchedule.filter(item => 
      type === 'proctor' ? item.proctor === nameOrNumber : item.room === nameOrNumber
    );
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-end px-6">
        <div>
            <h2 className="text-3xl font-black uppercase italic text-slate-900 tracking-tighter">Global <span className="text-blue-600">Resource</span> Monitor</h2>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em]">Live Status & Deployment Details</p>
        </div>
        <div className="relative">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={14}/>
            <input 
                type="text" 
                placeholder="Search staff or rooms..." 
                className="pl-10 pr-6 py-3 bg-white border-2 border-slate-100 rounded-2xl text-[10px] font-black uppercase w-64 focus:border-blue-500 outline-none transition-all shadow-sm"
                onChange={(e) => setSearchTerm(e.target.value.toUpperCase())}
            />
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* --- GLOBAL PROCTORS SECTION --- */}
        <section className="bg-white rounded-[2.5rem] shadow-xl border border-slate-100 overflow-hidden">
            <div className="bg-slate-900 p-6 text-white flex items-center justify-between">
                <div className="flex items-center gap-3">
                    <Users size={18} className="text-emerald-400" />
                    <h3 className="font-black uppercase tracking-widest text-[10px]">Staff Deployment List</h3>
                </div>
                <span className="bg-emerald-500/20 text-emerald-400 px-3 py-1 rounded-full text-[9px] font-black">{allProctors.length} Total</span>
            </div>
            <div className="p-4 max-h-[450px] overflow-y-auto space-y-2 custom-scrollbar">
                {allProctors.filter(p => p.name.includes(searchTerm)).map((proctor) => {
                    const assignments = getAssignments(proctor.name, 'proctor');
                    const isAssigned = assignments.length > 0;
                    const isOpen = expandedId === `p-${proctor.id}`;

                    return (
                        <div key={`proc-${proctor.id}`} className={`border-2 rounded-2xl overflow-hidden transition-all ${isAssigned ? 'border-amber-50' : 'border-slate-50'}`}>
                            <div 
                                onClick={() => toggleExpand(`p-${proctor.id}`)}
                                className="p-4 flex items-center justify-between cursor-pointer bg-white hover:bg-slate-50"
                            >
                                <div className="flex items-center gap-4">
                                    <div className={`w-2 h-2 rounded-full ${isAssigned ? 'bg-amber-500 animate-pulse' : 'bg-emerald-500'}`} />
                                    <div>
                                        <p className="text-xs font-black text-slate-800 uppercase leading-none mb-1">{proctor.name}</p>
                                        <p className="text-[9px] font-black text-slate-400 uppercase tracking-tighter">{proctor.deptCode} DEPARTMENT</p>
                                    </div>
                                </div>
                                <div className="flex items-center gap-4">
                                    <span className={`px-3 py-1 rounded-full text-[8px] font-black uppercase ${isAssigned ? 'bg-amber-100 text-amber-600' : 'bg-emerald-100 text-emerald-600'}`}>
                                        {isAssigned ? `${assignments.length} SESSIONS` : 'AVAILABLE'}
                                    </span>
                                    {isOpen ? <ChevronUp size={14} className="text-slate-300"/> : <ChevronDown size={14} className="text-slate-300"/>}
                                </div>
                            </div>

                            {isOpen && (
                                <div className="p-4 bg-slate-50 border-t-2 border-slate-100 space-y-3 animate-in slide-in-from-top-2 duration-200">
                                    {isAssigned ? assignments.map((asgn, idx) => (
                                        <div key={idx} className="bg-white p-4 rounded-xl shadow-sm border-l-4 border-blue-500">
                                            <div className="grid grid-cols-2 gap-y-3 gap-x-2 text-[9px] font-black uppercase">
                                                <div className="text-slate-400 flex items-center gap-2"><Calendar size={12} className="text-blue-500"/> {asgn.exam_date}</div>
                                                <div className="text-slate-400 flex items-center gap-2"><Clock size={12} className="text-blue-500"/> {asgn.start_time} - {asgn.end_time}</div>
                                                <div className="text-slate-900 bg-blue-50 px-2 py-1 rounded-md inline-block">SEC: {asgn.section}</div>
                                                <div className="text-slate-600 text-right">ROOM: {asgn.room}</div>
                                            </div>
                                            <div className="mt-3 text-[9px] text-blue-600 font-black italic border-t border-slate-100 pt-2 flex items-center gap-2">
                                                <BookOpen size={10}/> {asgn.subject_code} • {asgn.subject_name}
                                            </div>
                                        </div>
                                    )) : (
                                        <div className="text-center py-4">
                                            <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest italic">No active assignments</p>
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>
                    );
                })}
            </div>
        </section>

        {/* --- GLOBAL ROOMS SECTION --- */}
        <section className="bg-white rounded-[2.5rem] shadow-xl border border-slate-100 overflow-hidden">
            <div className="bg-slate-900 p-6 text-white flex items-center justify-between">
                <div className="flex items-center gap-3">
                    <DoorOpen size={18} className="text-amber-400" />
                    <h3 className="font-black uppercase tracking-widest text-[10px]">Room Allocation List</h3>
                </div>
                <span className="bg-amber-500/20 text-amber-400 px-3 py-1 rounded-full text-[9px] font-black">{allRooms.length} Total</span>
            </div>
            <div className="p-4 max-h-[450px] overflow-y-auto space-y-2 custom-scrollbar">
                {allRooms.filter(r => r.number.includes(searchTerm)).map((room) => {
                    const assignments = getAssignments(room.number, 'room');
                    const isAssigned = assignments.length > 0;
                    const isOpen = expandedId === `r-${room.id}`;

                    return (
                        <div key={`room-${room.id}`} className={`border-2 rounded-2xl overflow-hidden transition-all ${isAssigned ? 'border-rose-50' : 'border-slate-50'}`}>
                            <div 
                                onClick={() => toggleExpand(`r-${room.id}`)}
                                className="p-4 flex items-center justify-between cursor-pointer bg-white hover:bg-slate-50"
                            >
                                <div className="flex items-center gap-4">
                                    <div className={`w-2 h-2 rounded-full ${isAssigned ? 'bg-rose-500' : 'bg-emerald-500'}`} />
                                    <div>
                                        <p className="text-xs font-black text-slate-800 uppercase leading-none mb-1">ROOM {room.number}</p>
                                        <p className="text-[9px] font-black text-slate-400 uppercase tracking-tighter">{room.type} RESOURCE</p>
                                    </div>
                                </div>
                                <div className="flex items-center gap-4">
                                    <span className={`px-3 py-1 rounded-full text-[8px] font-black uppercase ${isAssigned ? 'bg-rose-100 text-rose-600' : 'bg-emerald-100 text-emerald-600'}`}>
                                        {isAssigned ? 'OCCUPIED' : 'VACANT'}
                                    </span>
                                    {isOpen ? <ChevronUp size={14} className="text-slate-300"/> : <ChevronDown size={14} className="text-slate-300"/>}
                                </div>
                            </div>

                            {isOpen && (
                                <div className="p-4 bg-slate-50 border-t-2 border-slate-100 space-y-3 animate-in slide-in-from-top-2 duration-200">
                                    {isAssigned ? assignments.map((asgn, idx) => (
                                        <div key={idx} className="bg-white p-4 rounded-xl shadow-sm border-l-4 border-amber-500">
                                            <div className="grid grid-cols-2 gap-y-3 gap-x-2 text-[9px] font-black uppercase">
                                                <div className="text-slate-400 flex items-center gap-2"><Calendar size={12} className="text-amber-500"/> {asgn.exam_date}</div>
                                                <div className="text-slate-400 flex items-center gap-2"><Clock size={12} className="text-amber-500"/> {asgn.start_time} - {asgn.end_time}</div>
                                                <div className="text-slate-900 bg-amber-50 px-2 py-1 rounded-md inline-block">SEC: {asgn.section}</div>
                                                <div className="text-slate-600 text-right truncate">STAFF: {asgn.proctor}</div>
                                            </div>
                                            <div className="mt-3 text-[9px] text-amber-600 font-black italic border-t border-slate-100 pt-2 flex items-center gap-2">
                                                <BookOpen size={10}/> EXAM: {asgn.subject_code}
                                            </div>
                                        </div>
                                    )) : (
                                        <div className="text-center py-4">
                                            <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest italic">Ready for Booking</p>
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>
                    );
                })}
            </div>
        </section>
      </div>
    </div>
  );
};

export default GlobalResourceMonitor;
